67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
75	     * owner's id, customer code, registration date and membership level, so the create side-effect
76	     * can be audited independently of the application log.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    /**
89	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
90	     * and a domain containing at least one dot, with no whitespace in any segment.
91	     */
92	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
93	
94	    /**
95	     * Required national-number length per E.164 country code. A normalized telephone whose country
96	     * code appears here must carry exactly this many national digits after the code; Australia
97	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
98	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
99	     */
100	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
101	
102	    /**
103	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
104	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
105	     */
106	    private static final int MAX_OWNERS_PER_CITY = 50;
107	
108	    /**
109	     * Maximum number of owners that may be registered on a single day (by registration date). A create
110	     * attempted once this many owners already carry today's registration date is rejected with a
111	     * 429 Too Many Requests.
112	     */
113	    private static final int MAX_OWNERS_PER_DAY = 100;
114	
115	    /**
116	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
117	     * owners already carry the new owner's registration date, the created owner is flagged
118	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
119	     */
120	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
121	
122	    /**
123	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
124	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
125	     */
126	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
127	        "ST", "STREET",
128	        "RD", "ROAD",
129	        "AVE", "AVENUE");
130	
131	    /**
132	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
133	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
134	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
135	     * 4-digit postcode.
136	     */
137	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
138	        "NSW", new int[] {2000, 2099},
139	        "VIC", new int[] {3000, 3099},
140	        "QLD", new int[] {4000, 4099});
141	
142	    public OwnerRestControllerV1(ClinicService clinicService,
143	                                 OwnerMapper ownerMapper,
144	                                 PetMapper petMapper,
145	                                 VisitMapper visitMapper) {
146	        this.clinicService = clinicService;
147	        this.ownerMapper = ownerMapper;
148	        this.petMapper = petMapper;
149	        this.visitMapper = visitMapper;
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
155	        Collection<Owner> owners;
156	        if (lastName != null) {
157	            owners = this.clinicService.findOwnerByLastName(lastName);
158	        } else {
159	            owners = this.clinicService.findAllOwners();
160	        }
161	        if (owners.isEmpty()) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
180	        validateRequiredFields(ownerFieldsDto);
181	        HttpHeaders headers = new HttpHeaders();
182	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
183	        rejectFutureRegistrationDate(owner.getRegistrationDate());
184	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
185	        owner.setRegistrationDate(registrationDate);
186	        requireDailyCapacity(registrationDate);
187	        requireCityHasCapacity(owner.getCity());
188	        validatePostcode(owner);
189	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
190	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
191	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
192	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
193	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
194	        requireNoHouseholdDuplicate(owner, declaredHouseholdMember);
195	        requireUniqueIdentity(owner);
196	        flagPossibleDuplicate(owner, declaredHouseholdMember);
197	        owner.setCustomerCode(owner.buildCustomerCode());
198	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
199	        stampHouseholdSize(owner);
200	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
201	        this.clinicService.saveOwner(owner);
202	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
203	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
204	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
205	        headers.setLocation(UriComponentsBuilder.newInstance()
206	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
207	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
208	    }
209	
210	    /**
211	     * Rejects a create whose supplied registration date is later than the server's current date. A
212	     * registration may be back-dated but never post-dated, so a future date is treated as a client
213	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
214	     * server date.
215	     *
216	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
217	     *     client omitted it
218	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
219	     */
220	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
221	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
222	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
223	        }
224	    }
225	
226	    /**
227	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
228	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
229	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
230	     * existed prior to this create.
231	     *
232	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
233	     *     a business day
234	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
235	     *     registered on that business day
236	     */
237	    private void requireDailyCapacity(LocalDate registrationDate) {
238	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
239	            throw new DailyOwnerLimitException(registrationDate);
240	        }
241	    }
242	
243	    /**
244	     * Counts the existing owners whose registration date equals the given business-day date. This is
245	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
246	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
247	     * the bulk-signup warning.
248	     *
249	     * @param registrationDate the effective business-day registration date to count against
250	     * @return the number of pre-existing owners registered on that date
251	     */
252	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
253	        return this.clinicService.findAllOwners().stream()
254	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
255	            .count();
256	    }
257	
258	    /**
259	     * Rejects an owner whose city already contains the maximum allowed number of owners
260	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
261	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
262	     * create.
263	     *
264	     * @param city the city of the owner being created
265	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
266	     */
267	    private void requireCityHasCapacity(String city) {
268	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
269	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
270	            .count();
271	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
272	            throw new CityOwnerLimitException(city);
273	        }
274	    }
275	
276	    /**
277	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
278	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
279	     * schema) that must fall within the inclusive range permitted for the region derived from the
280	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
281	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
282	     *
283	     * @param owner the owner being created, with its city and postcode set
284	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
285	     */
286	    private void validatePostcode(Owner owner) {
287	        String postcode = owner.getPostcode();
288	        if (postcode == null) {
289	            return;
290	        }
291	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
292	        if (range == null) {
293	            return;
294	        }
295	        int value = Integer.parseInt(postcode);
296	        if (value < range[0] || value > range[1]) {
297	            throw new InvalidOwnerFieldsException(List.of("postcode"));
298	        }
299	    }
300	
301	    /**
302	     * Counts the existing owners that already share the given first name and last name, compared
303	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
304	     * owners that existed prior to this create.
305	     *
306	     * @param firstName the first name of the owner being created
307	     * @param lastName the last name of the owner being created
308	     * @return the number of pre-existing namesakes
309	     */
310	    private int countNamesakes(String firstName, String lastName) {
311	        return (int) this.clinicService.findAllOwners().stream()
312	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
313	                && equalsIgnoreCase(existing.getLastName(), lastName))
314	            .count();
315	    }
316	
317	    /**
318	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
319	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
320	     *
321	     * @param a the first value, possibly {@code null}
322	     * @param b the second value, possibly {@code null}
323	     * @return whether the values are equal ignoring case
324	     */
325	    private boolean equalsIgnoreCase(String a, String b) {
326	        return a == null ? b == null : a.equalsIgnoreCase(b);
327	    }
328	
329	    /**
330	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
331	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
332	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
333	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
334	     *
335	     * @param ownerFieldsDto the submitted owner fields
336	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
337	     */
338	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
339	        List<String> invalidFields = new ArrayList<>();
340	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
341	            invalidFields.add("firstName");
342	        }
343	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
344	            invalidFields.add("lastName");
345	        }
346	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
347	            invalidFields.add("address");
348	        }
349	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
350	            invalidFields.add("city");
351	        }
352	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
353	            invalidFields.add("telephone");
354	        }
355	        if (!invalidFields.isEmpty()) {
356	            throw new InvalidOwnerFieldsException(invalidFields);
357	        }
358	    }
359	
360	    /**
361	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
362	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
363	     * what gets stored and returned.
364	     *
365	     * @param telephone the raw telephone value from the request
366	     * @return the normalized E.164 telephone number
367	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
368	     */
369	    private String normalizeTelephone(String telephone) {
370	        String e164 = toE164(telephone);
371	        if (e164 == null) {
372	            throw new InvalidOwnerFieldsException(List.of("telephone"));
373	        }
374	        return e164;
375	    }
376	
377	    /**
378	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
379	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
380	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
381	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
382	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
383	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
384	     *
385	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
386	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
387	     *
388	     * @param telephone the raw telephone value, possibly {@code null}
389	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
390	     */
391	    private String toE164(String telephone) {
392	        if (telephone == null) {
393	            return null;
394	        }
395	        String cleaned = telephone.replaceAll("[ \\-()]", "");
396	        String digits;
397	        if (cleaned.startsWith("+")) {
398	            digits = cleaned.substring(1);
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            digits = "61" + national;
402	        }
403	        if (!digits.matches("[0-9]{8,15}")) {
404	            return null;
405	        }
406	        if (!nationalNumberLengthValid(digits)) {
407	            return null;
408	        }
409	        return "+" + digits;
410	    }
411	
412	    /**
413	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
414	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
415	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
416	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
417	     * accepted, leaving only the generic total-length rule to apply.
418	     *
419	     * @param digits the E.164 digits without the leading {@code '+'}
420	     * @return {@code true} if the national-number length matches the country code's requirement
421	     */
422	    private boolean nationalNumberLengthValid(String digits) {
423	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
424	            String code = entry.getKey();
425	            if (digits.startsWith(code)) {
426	                return digits.length() - code.length() == entry.getValue();
427	            }
428	        }
429	        return true;
430	    }
431	
432	    /**
433	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
434	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
435	     * and returned lower-cased.
436	     *
437	     * @param email the raw email value from the request, possibly {@code null}
438	     * @return the lower-cased email, or {@code null} when none was supplied
439	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
440	     */
441	    private String normalizeEmail(String email) {
442	        if (!StringUtils.hasText(email)) {
443	            return null;
444	        }
445	        String trimmed = email.trim();
446	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
447	            throw new InvalidOwnerFieldsException(List.of("email"));
448	        }
449	        return trimmed.toLowerCase(Locale.ROOT);
450	    }
451	
452	    /**
453	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
454	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
455	     * owner's normalized telephone, email (empty when absent) and household id joined with
456	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
457	     * owner's. Because the telephone is part of the key, two members of the same household
458	     * (same {@code householdId}) with different telephones have different identity keys and are both
459	     * allowed.
460	     *
461	     * @param owner the owner being created, with its normalized telephone, email and household id set
462	     * @throws DuplicateIdentityException if another owner already has this identity key
463	     */
464	    private void requireUniqueIdentity(Owner owner) {
465	        String identityKey = owner.getIdentityKey();
466	        boolean inUse = this.clinicService.findAllOwners().stream()
467	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
468	        if (inUse) {
469	            throw new DuplicateIdentityException(identityKey);
470	        }
471	    }
472	
473	    /**
474	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
475	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
476	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
477	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
478	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
479	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
480	     * is false and {@code possibleDuplicateOf} is left unset.
481	     *
482	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
483	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
484	     *
485	     * @param owner the owner being created, with its normalized telephone and postcode set
486	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
487	     */
488	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
489	        if (declaredHouseholdMember || owner.getPostcode() == null) {
490	            owner.setPossibleDuplicate(false);
491	            return;
492	        }
493	        Integer matchId = this.clinicService.findAllOwners().stream()
494	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
495	                && owner.getPostcode().equals(existing.getPostcode())
496	                && !owner.getTelephone().equals(existing.getTelephone()))
497	            .map(Owner::getId)
498	            .min(Integer::compareTo)
499	            .orElse(null);
500	        owner.setPossibleDuplicate(matchId != null);
501	        owner.setPossibleDuplicateOf(matchId);
502	    }
503	
504	    /**
505	     * Rejects a create that would join an existing household unless it has opted in via
506	     * {@code sharesHousehold}. The household is keyed on the deterministic {@code householdId} (derived
507	     * from the normalized last name and postcode; see {@link #computeHouseholdId}), so any existing
508	     * owner carrying the same {@code householdId} is a member of the same household. When one exists and
509	     * the create has not declared household membership, the second owner is a household duplicate.
510	     *
511	     * <p>A create that declares {@code sharesHousehold} bypasses this block entirely and is created as a
512	     * declared household member.
513	     *
514	     * @param owner the owner being created, with its deterministic {@code householdId} already set
515	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
516	     * @throws DuplicateHouseholdException if an existing owner already shares the household and the
517	     *     create did not declare {@code sharesHousehold}
518	     */
519	    private void requireNoHouseholdDuplicate(Owner owner, boolean declaredHouseholdMember) {
520	        if (declaredHouseholdMember) {
521	            return;
522	        }
523	        String householdId = owner.getHouseholdId();
524	        boolean inUse = this.clinicService.findAllOwners().stream()
525	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
526	        if (inUse) {
527	            throw new DuplicateHouseholdException(householdId);
528	        }
529	    }
530	
531	    /**
532	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
533	     * the household - the existing owners that share the deterministic {@code householdId} and the new
534	     * one - so the shared size can be read back from any of them. The count is the number of existing
535	     * members plus the owner being created.
536	     *
537	     * @param owner the owner being created, with its deterministic {@code householdId} already set
538	     */
539	    private void stampHouseholdSize(Owner owner) {
540	        String householdId = owner.getHouseholdId();
541	        List<Owner> members = this.clinicService.findAllOwners().stream()
542	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
543	            .toList();
544	        int householdSize = members.size() + 1;
545	        owner.setHouseholdSize(householdSize);
546	        for (Owner member : members) {
547	            member.setHouseholdSize(householdSize);
548	            this.clinicService.saveOwner(member);
549	        }
550	    }
551	
552	    /**
553	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
554	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
555	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
556	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
557	     * shares a last name and postcode computes the same identifier and therefore the same household.
558	     *
559	     * @param lastName the last name of the household
560	     * @param postcode the postcode of the household, possibly {@code null}
561	     * @return the 12-character upper-case hex household identifier
562	     */
563	    private String computeHouseholdId(String lastName, String postcode) {
564	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
565	        try {
566	            byte[] digest = MessageDigest.getInstance("SHA-256")
567	                .digest(key.getBytes(StandardCharsets.UTF_8));
568	            StringBuilder hex = new StringBuilder(12);
569	            for (int i = 0; i < 6; i++) {
570	                hex.append(String.format("%02X", digest[i]));
571	            }
572	            return hex.toString();
573	        } catch (NoSuchAlgorithmException e) {
574	            throw new IllegalStateException("SHA-256 algorithm not available", e);
575	        }
576	    }
577	
578	    /**
579	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
580	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
581	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
582	     *
583	     * @param value the raw value, possibly {@code null}
584	     * @return the normalized value
585	     */
586	    private String normalizeForHousehold(String value) {
587	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
588	    }
589	
590	    /**
591	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
592	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
593	     * value yields an empty string.
594	     *
595	     * @param value the raw value, possibly {@code null}
596	     * @return the trimmed, whitespace-collapsed value
597	     */
598	    private String collapseWhitespace(String value) {
599	        if (value == null) {
600	            return "";
601	        }
602	        return value.trim().replaceAll("\\s+", " ");
603	    }
604	
605	    /**
606	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
607	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
608	     * is upper-cased, and common street-type abbreviations are expanded as whole words
609	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
610	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
611	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
612	     *
613	     * @param address the raw address value, possibly {@code null}
614	     * @return the normalized address
615	     */
616	    private String normalizeAddress(String address) {
617	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
618	        if (collapsed.isEmpty()) {
619	            return "";
620	        }
621	        String[] tokens = collapsed.split(" ");
622	        StringBuilder normalized = new StringBuilder();
623	        for (int i = 0; i < tokens.length; i++) {
624	            if (i > 0) {
625	                normalized.append(' ');
626	            }
627	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
628	        }
629	        return normalized.toString();
630	    }
631	
632	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
633	    @Override
634	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
635	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
636	        if (currentOwner == null) {
637	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
638	        }
639	        currentOwner.setAddress(ownerFieldsDto.getAddress());
640	        currentOwner.setCity(ownerFieldsDto.getCity());
641	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
642	        currentOwner.setLastName(ownerFieldsDto.getLastName());
643	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
644	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
645	        this.clinicService.saveOwner(currentOwner);
646	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
647	    }
648	
649	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
650	    @Transactional
651	    @Override
652	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
653	        Owner owner = this.clinicService.findOwnerById(ownerId);
654	        if (owner == null) {
655	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
656	        }
657	        this.clinicService.deleteOwner(owner);
658	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
659	    }
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Override
663	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
664	        Owner owner = this.clinicService.findOwnerById(ownerId);
665	        if (owner == null) {
666	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
667	        }
668	        HttpHeaders headers = new HttpHeaders();
669	        Pet pet = petMapper.toPet(petFieldsDto);
670	        owner.setId(ownerId);
671	        pet.setOwner(owner);
672	        pet.getType().setName(null);
673	        this.clinicService.savePet(pet);
674	        PetDto petDto = petMapper.toPetDto(pet);
675	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
676	            .buildAndExpand(pet.getId()).toUri());
677	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
678	    }
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Override
682	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
683	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
684	        if (currentOwner != null) {
685	            Pet currentPet = this.clinicService.findPetById(petId);
686	            if (currentPet != null) {
687	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
688	                currentPet.setName(petFieldsDto.getName());
689	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
690	                this.clinicService.savePet(currentPet);
691	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
692	            }
693	        }
694	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
695	    }
696	
697	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
698	    @Override
699	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
700	        HttpHeaders headers = new HttpHeaders();
701	        Visit visit = visitMapper.toVisit(visitFieldsDto);
702	        Pet pet = new Pet();
703	        pet.setId(petId);
704	        visit.setPet(pet);
705	        this.clinicService.saveVisit(visit);
706	        VisitDto visitDto = visitMapper.toVisitDto(visit);
707	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
708	            .buildAndExpand(visit.getId()).toUri());
709	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
710	    }
711	
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
716	        Owner owner = this.clinicService.findOwnerById(ownerId);
717	        if (owner != null) {
718	            Pet pet = owner.getPet(petId);
719	            if (pet != null) {
720	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
721	            }
722	        }
723	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
724	    }
725	}
