31	/**
32	 * Simple JavaBean domain object representing an owner.
33	 *
34	 * @author Ken Krebs
35	 * @author Juergen Hoeller
36	 * @author Sam Brannen
37	 * @author Michael Isvy
38	 */
39	@Entity
40	@Table(name = "owners")
41	public class Owner extends Person {
42	    @Column(name = "address")
43	    @NotEmpty
44	    private String address;
45	
46	    @Column(name = "city")
47	    @NotEmpty
48	    private String city;
49	
50	    @Column(name = "telephone")
51	    @NotEmpty
52	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (a '+' followed by 8 to 15 digits)")
53	    private String telephone;
54	
55	    @Column(name = "email")
56	    private String email;
57	
58	    @Column(name = "registration_date", columnDefinition = "DATE")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date", columnDefinition = "DATE")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "postcode")
77	    private String postcode;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    /**
92	     * Fixed city-to-region table used to derive {@link #getLocality() locality} when the postcode
93	     * is absent or in no known range. Any city not listed derives the locality {@code 'UNKNOWN'}.
94	     */
95	    private static final Map<String, String> CITY_REGION = Map.of(
96	        "Sydney", "NSW",
97	        "Melbourne", "VIC",
98	        "Brisbane", "QLD");
99	
100	    /**
101	     * Inclusive 4-digit postcode range per region, used to derive {@link #getLocality() locality}
102	     * from the postcode in preference to the city: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
103	     */
104	    private static final Map<String, int[]> REGION_POSTCODE = Map.of(
105	        "NSW", new int[] {2000, 2099},
106	        "VIC", new int[] {3000, 3099},
107	        "QLD", new int[] {4000, 4099});
108	
109	    public String getAddress() {
110	        return this.address;
111	    }
112	
113	    public void setAddress(String address) {
114	        this.address = address;
115	    }
116	
117	    public String getCity() {
118	        return this.city;
119	    }
120	
121	    public void setCity(String city) {
122	        this.city = city;
123	    }
124	
125	    public String getTelephone() {
126	        return this.telephone;
127	    }
128	
129	    public void setTelephone(String telephone) {
130	        this.telephone = telephone;
131	    }
132	
133	    public String getEmail() {
134	        return this.email;
135	    }
136	
137	    public void setEmail(String email) {
