157	    /**
158	     * The owner's age band, derived from the {@link #getBirthDate() birth date} as at the owner's
159	     * {@link #getRegistrationDate() registration date}: {@code 'MINOR'} when under 18, {@code 'ADULT'}
160	     * when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is the number of whole years
161	     * elapsed from the birth date to the registration date (defaulting to the server's current date
162	     * when no registration date is set yet). Returns {@code null} when no birth date was supplied.
163	     *
164	     * @return the age band, or {@code null} when the birth date is absent
165	     */
166	    public String getAgeBand() {
167	        if (this.birthDate == null) {
168	            return null;
169	        }
170	        LocalDate asAt = this.registrationDate != null ? this.registrationDate : LocalDate.now();
171	        int years = Period.between(this.birthDate, asAt).getYears();
172	        if (years < 18) {
173	            return "MINOR";
174	        }
175	        if (years < 65) {
176	            return "ADULT";
177	        }
178	        return "SENIOR";
179	    }
180	
181	    public String getCustomerCode() {
182	        return this.customerCode;
183	    }
184	
185	    public void setCustomerCode(String customerCode) {
186	        this.customerCode = customerCode;
187	    }
188	
189	    /**
190	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
191	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
192	     * from the owner's own customer code and registration date; {@code null} when either is absent.
193	     *
194	     * @return the membership number, or {@code null} when it cannot be derived
195	     */
196	    public String getMembershipNumber() {
197	        if (this.customerCode == null || this.registrationDate == null) {
198	            return null;
199	        }
200	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
201	    }
202	
203	    /**
204	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
205	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
206	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
207	     *
208	     * @return the Luhn check digit, or {@code null} when the customer code is absent
209	     */
210	    public Integer getCheckDigit() {
211	        if (this.customerCode == null) {
212	            return null;
213	        }
214	        int sum = 0;
215	        boolean dbl = true;
216	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
217	            char c = this.customerCode.charAt(i);
218	            if (c < '0' || c > '9') {
219	                continue;
220	            }
221	            int d = c - '0';
222	            if (dbl) {
223	                d *= 2;
224	                if (d > 9) {
225	                    d -= 9;
226	                }
227	            }
228	            sum += d;
229	            dbl = !dbl;
230	        }
231	        return (10 - (sum % 10)) % 10;
232	    }
233	
234	    /**
235	     * The owner's numeric membership level, derived from the values frozen at create time. It starts
236	     * at 1, gains 1 when an email address is present, gains 1 when the owner has no namesakes
237	     * ({@code namesakeCount} is 0), and is capped at 3. Level 4 is reserved for tenure.
238	     *
239	     * @return the membership level, an integer from 1 to 3
240	     */
241	    public Integer getMembershipLevel() {
242	        int level = 1;
243	        boolean hasEmail = this.email != null && !this.email.isBlank();
244	        if (hasEmail) {
245	            level++;
246	        }
247	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
248	        if (hasNoNamesakes) {
249	            level++;
250	        }
251	        return Math.min(level, 3);
252	    }
253	
254	    /**
255	     * The owner's locality, the canonical region string. Once the owner has a
256	     * {@link #getCustomerCode() customer code} the locality is the {@code <REGION>} component of that
257	     * code (the text before the first {@code '-'}), so the locality and the identity share a single
258	     * source of truth. Before the customer code is assigned (for example while a create is still
259	     * validating the postcode) it falls back to the region the code will be built from: the
260	     * {@link #getPostcode() postcode} looked up by range first (NSW 2000-2099, VIC 3000-3099,
261	     * QLD 4000-4099), then the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
262	     * Brisbane->QLD), and finally {@code 'UNKNOWN'} when neither resolves to a region.
263	     *
264	     * @return the canonical region string, or {@code 'UNKNOWN'}
265	     */
266	    public String getLocality() {
267	        if (this.customerCode != null) {
268	            int dash = this.customerCode.indexOf('-');
269	            return dash >= 0 ? this.customerCode.substring(0, dash) : this.customerCode;
270	        }
271	        return deriveRegion();
272	    }
273	
274	    /**
275	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
276	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
277	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
278	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
279	     * the same region for known cities but disambiguates cities that share a name.
280	     *
281	     * @return the canonical region string, or {@code 'UNKNOWN'}
282	     */
283	    private String deriveRegion() {
284	        String region = regionFromPostcode();
285	        if (region != null) {
286	            return region;
287	        }
288	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
289	    }
290	
291	    /**
292	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
293	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
294	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
295	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
296	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
297	     * owner's region, telephone and last name. Call this once at create time and store the result via
298	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
299	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
300	     *
301	     * @return the assembled customer code
302	     */
303	    public String buildCustomerCode() {
304	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
305	    }
306	
307	    /**
308	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
309	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
310	     *
311	     * @param value the value to hash
312	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
313	     */
314	    private static String sha256Hex8(String value) {
315	        try {
316	            byte[] digest = MessageDigest.getInstance("SHA-256")
317	                .digest(value.getBytes(StandardCharsets.UTF_8));
318	            StringBuilder hex = new StringBuilder(8);
319	            for (int i = 0; i < 4; i++) {
320	                hex.append(String.format("%02X", digest[i]));
321	            }
322	            return hex.toString();
323	        }
324	        catch (NoSuchAlgorithmException e) {
325	            throw new IllegalStateException("SHA-256 algorithm not available", e);
326	        }
327	    }
328	
329	    /**
330	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
331	     * absent, not a 4-digit number, or in no known range.
332	     *
333	     * @return the matching region, or {@code null}
334	     */
335	    private String regionFromPostcode() {
336	        if (this.postcode == null) {
337	            return null;
338	        }
339	        int value;
340	        try {
341	            value = Integer.parseInt(this.postcode.trim());
342	        }
343	        catch (NumberFormatException ex) {
344	            return null;
345	        }
346	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
347	            int[] range = entry.getValue();
348	            if (value >= range[0] && value <= range[1]) {
349	                return entry.getKey();
350	            }
351	        }
352	        return null;
353	    }
354	
355	    /**
356	     * The owner's preferred contact channel, derived from the owner's details. Returns
357	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
358	     *
359	     * @return {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}
360	     */
361	    public String getContactPreference() {
362	        boolean hasEmail = this.email != null && !this.email.isBlank();
363	        return hasEmail ? "EMAIL" : "PHONE";
364	    }
365	
366	    /**
367	     * The owner's identity key, the single derived value used for duplicate detection. It is the
368	     * owner's normalized telephone, email (empty when absent) and household id joined with
369	     * {@code '|'} ({@code '<telephone>|<email>|<householdId>'}); any absent ({@code null}) component
370	     * contributes an empty string. Two owners are duplicates exactly when their whole identity keys
371	     * are equal, so two members of the same household with different telephones differ here and are
372	     * both allowed.
373	     *
374	     * @return the derived identity key
375	     */
376	    public String getIdentityKey() {
377	        return (this.telephone == null ? "" : this.telephone) + "|"
378	            + (this.email == null ? "" : this.email) + "|"
379	            + (this.householdId == null ? "" : this.householdId);
380	    }
