438	    /**
439	     * Stamps the effective registration date exactly once on insert, so every newly persisted owner
440	     * carries a resolved, business-day registration date (see {@link #resolveRegistrationDate}).
441	     */
442	    @PrePersist
443	    void onCreate() {
444	        this.registrationDate = resolveRegistrationDate(this.registrationDate);
445	    }
446	
447	    /**
448	     * Resolves the effective registration date and rolls it onto a business day. An absent
449	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
450	     * The resulting date is then rolled forward so it never falls on a weekend: a Saturday or Sunday
451	     * becomes the following Monday, while any weekday is returned unchanged.
452	     *
453	     * <p>This is the single definition of both the defaulting and the business-day roll, used
454	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
455	     * stamps the owner and by the create endpoint that counts owners per business day.
456	     *
457	     * @param supplied the registration date from the request, or {@code null} when none was supplied
458	     * @return the effective registration date, guaranteed to fall on a business day
459	     */
460	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
461	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
462	        return switch (effective.getDayOfWeek()) {
463	            case SATURDAY -> effective.plusDays(2);
464	            case SUNDAY -> effective.plusDays(1);
465	            default -> effective;
466	        };
467	    }
468	
469	    protected Set<Pet> getPetsInternal() {
470	        if (this.pets == null) {
471	            this.pets = new HashSet<>();
472	        }
473	        return this.pets;
474	    }
