481	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
482	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
483	        return Collections.unmodifiableList(sortedPets);
484	    }
485	
486	    public void setPets(List<Pet> pets) {
487	        this.pets = new HashSet<>(pets);
488	    }
489	
490	    public void addPet(Pet pet) {
491	        getPetsInternal().add(pet);
492	        pet.setOwner(this);
493	    }
494	
495	    /**
496	     * Return the Pet with the given name, or null if none found for this Owner.
497	     *
498	     * @param name to test
499	     * @return true if pet name is already in use
500	     */
501	    public Pet getPet(String name) {
502	        return getPet(name, false);
503	    }
504	
505	    /**
506	     * Return the Pet with the given name, or null if none found for this Owner.
507	     *
508	     * @param name to test
509	     * @return true if pet name is already in use
510	     */
511	    public Pet getPet(String name, boolean ignoreNew) {
512	        name = name.toLowerCase();
513	        for (Pet pet : getPetsInternal()) {
514	            if (!ignoreNew || !pet.isNew()) {
515	                String compName = pet.getName();
516	                compName = compName.toLowerCase();
517	                if (compName.equals(name)) {
518	                    return pet;
519	                }
520	            }
521	        }
522	        return null;
523	    }
524	
525	    public Pet getPet(Integer petId) {
526	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
527	    }
528	
529	    @Override
530	    public String toString() {
531	        return new ToStringCreator(this)
532	
533	            .append("id", this.getId())
534	            .append("new", this.isNew())
535	            .append("lastName", this.getLastName())
536	            .append("firstName", this.getFirstName())
537	            .append("address", this.address)
538	            .append("city", this.city)
539	            .append("telephone", this.telephone)
540	            .toString();
541	    }
542	}
